536	\begin{definition}[Lines]\label{def:line}
537		A \emph{line} $\ell$ in $\F_q^m$ specified by a pair
538		$(u,v) \in (\F_q^m)^2$ is the subset
539		\begin{equation}\label{eq:line-set}
540			\ell(u,v) = \bigl\{\, u + tv : t \in \F_q \,\bigr\} \subseteq \F_q^m\;.
541		\end{equation}
542		The vector $v$ is called a \emph{direction} of $\ell(u,v)$; the case $v = 0$
543		is explicitly allowed, in which case the line is the singleton $\{u\}$. A
544		line $\ell(u,v)$ is \emph{axis-parallel} if there is a coordinate
545		$i \in \{1, \dots, m\}$ for which $v = e_i$, the $i$-th elementary basis
546		vector of $\F_q^m$; such a line is said to be \emph{parallel to the $i$-th
547		direction}. A line $\ell(u,v)$ is \emph{diagonal} if there exists
548		$i \in \{0, 1, \dots, m-1\}$ such that $v_1 = v_2 = \dots = v_i = 0$ (for
549		$i = 0$ the condition is vacuous, so every line is diagonal).
550	\end{definition}
551	
552	\begin{proposition}\label{prop:line-equiv}
553		\lean{MIPStarRE.QPBT.linePoints_eq_of_mem}
554		\leanok
555		\uses{def:line}
556		Let $u, v \in \F_q^m$. Then for all $u' \in \ell(u,v)$, we have
557		$\ell(u,v) = \ell(u',v)$.
558	\end{proposition}
559	\begin{proof}
560		\leanok
561		\uses{def:line}
562		Fix $u' \in \ell(u,v)$, so $u' = u + tv$ for some $t \in \F_q$. Any
563		$a \in \ell(u,v)$ has the form $a = u + sv = u' + (s - t)v$, so
564		$\ell(u,v) \subseteq \ell(u',v)$. The symmetric argument gives the reverse
565		inclusion.
566	\end{proof}
567	
568	Thus, for a fixed direction, a line is an equivalence class of its points: the
569	pair $(u,v)$ representing it can use any base point on the line. A canonical
570	representation is obtained as follows.
571	
572	\begin{definition}[Canonical representative of a line]\label{def:line-representative}
573		\uses{def:line, def:cl-canonical, prop:line-equiv}
574		Let $\ell$ be a line in direction $v \neq 0$, and let
575		$L^{\mathrm{Ln}}_v : \F_q^m \to \F_q^m$ denote the canonical linear map with
576		the one-dimensional kernel basis $\{v\}$
577		(Definition~\ref{def:cl-canonical}). The \emph{canonical representative of
578		$\ell$} is the point $u_0 \in \F_q^m$ such that
579		\[
580			u_0 = L^{\mathrm{Ln}}_v(u) \qquad \text{for all } u \in \ell\;.
581		\]
582		This is well defined: since the image and kernel of $L^{\mathrm{Ln}}_v$ are
583		complementary, any $u \in \ell$ decomposes uniquely as $u = u_0 + tv$ with
584		$u_0$ in the image, so $u_0 = u - tv \in \ell$ and
585		$L^{\mathrm{Ln}}_v(u_0) = u_0$; moreover any two points of $\ell$ differ by
586		a multiple of $v$ and therefore have the same image under
587		$L^{\mathrm{Ln}}_v$. A line $\ell = \ell(u,v)$ is henceforth canonically
588		represented by the pair $(u_0, v)$. (For $v = 0$, where the singleton
589		$\{u\}$ leaves no independent kernel basis, we take $L^{\mathrm{Ln}}_0$ to
590		be the identity---the canonical linear map with empty kernel basis---so
591		that $u_0 = u$; the source leaves this case implicit.)
592	\end{definition}
