628	\begin{definition}[State space of a linear register]\label{def:lin-reg}
629		\uses{def:complementary}
630		For a set $V$, we write $\C^V$ for the complex vector space of dimension
631		$|V|$, endowed with the canonical orthonormal basis
632		$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
633		$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
634		subspaces over $\F$, then $\C^V$ is identified with
635		$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
636		$\ket{x_1 \oplus \dots \oplus x_k}$ with
637		$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
638		$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
639		$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
640		the \emph{qudits} of $\C^V$.
641	\end{definition}
642	
643	\begin{definition}[EPR state]\label{def:EPR}
644		\lean{MIPStarRE.QPBT.eprState}
645		\leanok
646		\uses{def:lin-reg}
647		For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
648		$\C^V \ot \C^V$ is
649		\[
650			\ket{\mathrm{EPR}}_V
651			= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
652		\]
653		We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
654		$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
655	\end{definition}
