665	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
666		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
667		\lean{MIPStarRE.QPBT.primeTauObservable}
668		\lean{MIPStarRE.QPBT.pauliVec, MIPStarRE.QPBT.pauliProj}
669		\uses{def:subfield-trace, def:lin-reg}
670		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
671		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
672		\begin{equation}\label{eq:pauli-fp}
673			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
674			\qquad \text{and} \qquad
675			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
676		\end{equation}
677		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
678		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
679		$\C^{\F_q}$
680		\[
681			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
682			\qquad \text{and} \qquad
683			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
684		\]
685		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
686		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
687		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
688		signs. All the $\tau^X$ operators commute with one another, as do all the
689		$\tau^Z$ operators. Their common eigenbases consist of the vectors
690		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
691		\[
692			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
693			\omega^{-\tr(ej)} \ket{j}\;, \qquad
694			\ket{e_Z} = \ket{e}\;;
695		\]
696		the Fourier transform
697		\begin{equation}\label{eq:fourier-f}
698			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
699			\omega^{-\tr(ab)} \ket{a}\bra{b}
700		\end{equation}
701		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
702		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
703		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
704		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
705		\[
706			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
707			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
708		\]
709		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
710		The distinction between the general prime-characteristic definitions and
711		the characteristic-two specializations used by the Pauli basis test is
712		documented in \cite{gap:qpbt_characteristic-two-pauli-scope}.
713	\end{definition}
