723		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
724		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
725		\begin{enumerate}
726			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
727			      \begin{equation}\label{eq:pauli-product-power}
728				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
729				      \qquad \text{and} \qquad
730				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
731			      \end{equation}
732			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
733			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
734			      $p$-th roots of unity.
735			\item For all $a, b \in \F_q^n$,
736			      % Paper equation label kept on the display it names.
737			      \begin{equation}\label{eq:twisted-fq}
738				      \tau^X(a)\, \tau^Z(b)
739				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
740			      \end{equation}
741			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
742			      $q = p$, $n = 1$ reads
743			      \begin{equation}\label{eq:twisted-fp}
744				      \sigma^X(a)\, \sigma^Z(b)
745				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
746				      \qquad \text{for all } a, b \in \F_p\;.
747			      \end{equation}
748		\end{enumerate}
749	\end{lemma}
